"""Fixed-width EXPORT_ACCT record formatter."""

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


def _is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _fixed(value: Any, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    if _is_blank(value):
        amount = Decimal(0)
    elif isinstance(value, Decimal):
        amount = value
    else:
        amount = Decimal(str(value))

    precision = max(50, len(amount.as_tuple().digits) + 10)
    with localcontext() as context:
        context.prec = precision
        cents = (amount * Decimal(100)).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )

    return str(int(cents)).zfill(width)


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT fixed-width record."""
    credit_hold = row.get("CRED_HOLD", "")
    if _is_blank(credit_hold):
        credit_hold = "N"
    else:
        credit_hold = str(credit_hold)

    create_date = row.get("CREATE_DT", "")
    if _is_blank(create_date):
        create_date = "00000000"
    else:
        create_date = str(create_date)

    record = (
        _fixed(row.get("ACCT_ID", ""), 10)
        + _fixed(row.get("ACCT_NM", ""), 40)
        + _fixed(row.get("REGION_CD", ""), 3)
        + _zpad_cents(row.get("ANN_REV", ""), 15)
        + credit_hold
        + create_date
    )

    if len(record) != 77:
        raise ValueError("EXPORT_ACCT source values violate the fixed-width layout")

    return record
